<?php

declare(strict_types=1);

namespace Runalyze\Calculation\Trimp;

/**
 * Generated by PHPUnit_SkeletonGenerator 1.2.0 on 2014-10-11 at 09:00:23.
 */
#[\PHPUnit\Framework\Attributes\Group('default')]
final class DataCollectorTest extends \PHPUnit\Framework\TestCase
{
    public function testSingleValueWithoutDuration(): void
    {
        $Collector = new DataCollector(
            [140]
        );

        $this->assertEquals([
            140 => 1,
        ], $Collector->result());
    }

    public function testSingleValueWithDuration(): void
    {
        $Collector = new DataCollector(
            [150],
            [60]
        );

        $this->assertEquals([
            150 => 60,
        ], $Collector->result());
    }

    public function testArrayWithoutDuration(): void
    {
        $Collector = new DataCollector(
            [140, 145, 140, 150, 160, 175, 190, 150, 145, 140]
        );

        $this->assertEquals([
            140 => 3,
            145 => 2,
            150 => 2,
            160 => 1,
            175 => 1,
            190 => 1,
        ], $Collector->result());
    }

    public function testArrayWithDuration(): void
    {
        $Collector = new DataCollector(
            [140, 145, 140, 150, 160, 175, 190, 150, 145, 140],
            [60, 90, 100, 140, 170, 190, 200, 230, 290, 300]
        );

        $this->assertEquals([
            140 => 80,
            145 => 90,
            150 => 70,
            160 => 30,
            175 => 20,
            190 => 10,
        ], $Collector->result());
    }

    public function testThrowsExceptionForEmptyHeartRateArray(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessageIsOrContains('Heart rate array must not be empty.');

        new DataCollector([]);
    }

    public function testThrowsExceptionWhenDurationSizeDoesNotMatchHeartRateSize(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessageIsOrContains('Heart rate and duration array must be of equal size.');

        new DataCollector([140, 150], [60]);
    }
}
